    __typename
  }
  kakuyomuOfficialAdminUser {
    id
    textualWorkReviews(first: 4) {
      nodes {
        id
        ...OfficialReviewBox_TextualWorkReview
        __typename
      }
      __typename
    }
    __typename
  }
  topicalWorkSelection {
    id
    title
    works {
      id
      ...PreviewWorkBox_Work
      __typename
    }
    __typename
  }
  userEvents(first: 12, status: OPEN, enteredWorkMinCount: 20) {
    nodes {
      id
      ...UserEventBox_UserEvent
      __typename
    }
    __typename
  }
  worksInLastEpisodePublishedOrder(first: 12) {
    nodes {
      id
      ...PreviewWorkBox_Work
      __typename
    }
    __typename
  }
  newRunningWorks: searchWorks(order: PUBLISHED_AT, first: 12) {
    nodes {
      id
      ...PreviewWorkBox_Work
      __typename
    }
    __typename
  }
  recentlyCompletedWorks: searchWorks(
    serialStatus: COMPLETED
    totalCharacterMinCount: 20000
    order: LAST_EPISODE_PUBLISHED_AT
    first: 12
  ) {
    nodes {
      id
      ...PreviewWorkBox_Work
      __typename
    }
    __typename
  }
