query GetNotFoundPage($recommendedWorksLimit: Int!, $recommendedKeywordsLimit: Int!, $publicationWorksLimit: Int!, $weeklyRankedWorksLimit: Int!, $genres: [Work_Genre!]!, $hasWork: Boolean!, $workId: ID!) {
  visitor {
    id
    ...DefaultTemplate_Visitor
    ...NotFoundHeader_Visitor
    __typename
  }
  recommendedWorksInRandomOrder(limit: $recommendedWorksLimit) {
    id
    ...TopStartWithWorks_Work
    __typename
  }
  recommendedKeywordsInRandomOrder(limit: $recommendedKeywordsLimit)
  publicationWorks(first: $publicationWorksLimit) {
    nodes {
      id
      ...TopRecentPublicationWorks_Work
      __typename
    }
    __typename
  }
  activeWorkShowcase {
    ...TopWorkShowcase_WorkShowcase
    __typename
  }
  searchWorks(first: 1) {
    totalCount
    __typename
  }
  genredWorkCounts(genres: $genres)
  rankedWorks(period: WEEKLY, first: $weeklyRankedWorksLimit) {
    nodes {
      id
      ...TopWeeklyRankedWork_Work
      __typename
    }
    __typename
  }
  ... on Query @include(if: $hasWork) {
    works(ids: [$workId]) {
      ...NotFoundHeader_Work
      __typename
    }
    __typename
  }
}

