    closedUserEvents: enteringUserEvents(first: 3, status: CLOSED) {
      nodes {
        id
        ...EventItem_UserEvent
        __typename
      }
      totalCount
      __typename
    }
    ...WorkTemplate_Work
    ...UseWorkTitle_Work
    ...UseWorkAuthorName_Work
    __typename
  }
  visitor {
    id
    ...WorkTemplate_Visitor
    __typename
  }
}

