query GetWorkPage($workId: ID!, $isWorkTocV2: Boolean!) {
  visitor {
    id
    ...DefaultTemplate_Visitor
    ...WorkAuthorBox_Visitor
    __typename
  }
  work(id: $workId) {
    id
    ...WorkHeader_Work
    ...WorkSubHeader_Work
    ...WorkIntroductionBox_Work
    ...WorkReviewsBox_Work
    ...WorkMeta_Work
    relatedWorks(limit: 30) {
      id
      ...CatchphraseWorkBox_Work
      ...RelatedWorks_Work
      __typename
    }
    ...WorkReviewButton_Work
    ...WorkDetail_Work
    ...CompactWorkFooter_Work
    tableOfContents @skip(if: $isWorkTocV2) {
      id
      episodeUnions {
        ... on Episode {
          id
          __typename
        }
        ... on EmptyEpisode {
          id
          __typename
        }
        ...PromoteEnterKakuyomuNextModal_EpisodeUnion
        __typename
      }
      __typename
    }
    tableOfContentsV2 @include(if: $isWorkTocV2) {
      id
      episodeUnions {
        ... on Episode {
          id
          __typename
        }
        ... on EmptyEpisode {
          id
          __typename
        }
        ...PromoteEnterKakuyomuNextModal_EpisodeUnion
        __typename
      }
      __typename
    }
    ...WorkTocSection_Work
    ...WorkAuthorBox_Work
    ...WorkContestBox_Work
    visitorReadingHistory {
      id
      ...WorkTocReadingHistory_ReadingHistory
      __typename
    }
    ...UseWorkTitle_Work
    ...UseWorkAuthorName_Work
    ogImageUrl
    kakuyomuNextWork {
      id
      ...KakuyomuNextLogo_KakuyomuNextWork
      __typename
    }
    ...PromoteEnterKakuyomuNextModal_Work
    ...WorkReservation_Work
    catchphrase
    introduction
    tagLabels
    genre
    publicEpisodeCount
    editedAt
    adBypass
    adUnsafe
    canShowAdForVisitor
    canShowAsBlogInHatenaBookmark
    mediaMix {
      id
      ...MediaMixInfoCell_WorkMediaMix
      mediaMixContents {
        id
        ...MediaMixInfoCell_MediaMixContent
        __typename
      }
      __typename
    }
    author {
      id
      name
      publicationLabel {
        id
        __typename
      }
      __typename
    }
    ...WorkMediaMixLinkBox_Work
    publicMediaFranchisedWorks {
      totalCount
      nodes {
        id
        ...WorkPublicationSeriesList_MediaFranchisedWork
        __typename
      }
      __typename
    }
    __typename
  }
  mediaFranchisedWorkProviders {
    id
    ...PublicationProductAttributeList_MediaFranchisedWorkProvider
    __typename
  }
}

