query GetWorkReviewsPage($workId: ID!, $first: Int!, $offset: Int, $filter: TextualWorkReviews_Filter, $order: WorkReview_SortOrder) {
  work(id: $workId) {
    id
    ...WorkTemplate_Work
    ...UseWorkTitle_Work
    ...UseWorkAuthorName_Work
    ...WorkReviewList_Work
    ...WorkReviewsSummary_Work
    ...WorkReviewFilter_Work
    textualWorkReviews(
      first: $first
      offset: $offset
      filter: $filter
      order: $order
    ) {
      nodes {
        id
        ...WorkReviewList_WorkReview
        __typename
      }
      pageInfo {
        ...RouterPager_PageInfo
        __typename
      }
      __typename
    }
    __typename
  }
  visitor {
    id
    ...WorkTemplate_Visitor
    __typename
  }
}

